-- models/marts/fct_orders.sql
{{
  config(
    materialized='incremental',
    unique_key='order_id',
    incremental_strategy='merge',
    on_schema_change='append_new_columns'
  )
}}

with source as (
    select
        order_id,
        customer_id,
        status,
        amount,
        updated_at
    from {{ ref('stg_orders') }}

    {% if is_incremental() %}
    -- only process rows newer than what we already have,
    -- with a 3-day lookback to catch late-arriving updates
    where updated_at >= (
        select dateadd(day, -3, max(updated_at)) from {{ this }}
    )
    {% endif %}
)

select * from source

-- models/marts/fct_events.sql  (BigQuery: insert_overwrite)
{{
  config(
    materialized='incremental',
    incremental_strategy='insert_overwrite',
    partition_by={'field': 'event_date', 'data_type': 'date'},
    cluster_by=['event_type']
  )
}}

select
    event_id,
    event_type,
    user_id,
    event_timestamp,
    date(event_timestamp) as event_date
from {{ ref('stg_events') }}
{% if is_incremental() %}
where date(event_timestamp) >= date_sub(current_date(), interval 3 day)
{% endif %}

